def can_rearrange(s):
    from collections import Counter
    char_count = Counter(s)
    max_count = max(char_count.values())
    if max_count > (len(s) + 1) // 2:
        return False
    if len(s) % 2 == 0:
        odd_counts = sum(1 for count in char_count.values() if count % 2 != 0)
        if odd_counts > 0:
            return False
    else:
        odd_counts = sum(1 for count in char_count.values() if count % 2 != 0)
        if odd_counts > 1:
            return False
    return True
```

