def last_digit_factorial_division(b, a):
    if a >= b:
        return 0
    factorial_a = 1
    for i in range(2, a + 1):
        factorial_a = (factorial_a * i) % 10
    factorial_b = 1
    for i in range(2, b + 1):
        factorial_b = (factorial_b * i) % 10
    return factorial_b // factorial_a % 10
```

