```python
def eulerian_number(n, m):
    if m == 0:
        return 1 if n == 0 else 0
    if m == n:
        return 1
    if n < m:
        return 0
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        dp[i][0] = i * dp[i - 1][0] + dp[i - 1][1]
        for j in range(1, min(i, m) + 1):
            dp[i][j] = (i - 1) * (dp[i - 1][j - 1] + dp[i - 1][j])
    return dp[n][m]
```

