def count_odd_rotations(binary_str):
    def rotate_str(s, k):
        return s[k:] + s[:k]

    count = 0
    n = len(binary_str)
    for i in range(n):
        rotated_str = rotate_str(binary_str, i)
        if int(rotated_str, 2) % 2 != 0:
            count += 1
    return count
```

