def is_smart_number(x):
    if x <= 0:
        return False
    divisors = 0
    for i in range(1, int(x**0.5) + 1):
        if x % i == 0:
            divisors += 1
            if i != x // i:
                divisors += 1
    return divisors == 4

def nth_smart_number(n):
    count = 0
    num = 1
    while True:
        if is_smart_number(num):
            count += 1
            if count == n:
                return num
        num += 1
