def sum_common_divisors(a, b):
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    def sum_divisors(n):
        divisors_sum = 0
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                divisors_sum += i
                if i != n // i:
                    divisors_sum += n // i
        return divisors_sum

    common_gcd = gcd(a, b)
    return sum_divisors(common_gcd)
```

