def is_magic_square(square):
    n = len(square)
    if any(len(row) != n for row in square):
        return False
    magic_sum = sum(square[0])
    for row in square:
        if sum(row) != magic_sum:
            return False
    for col in range(n):
        if sum(square[row][col] for row in range(n)) != magic_sum:
            return False
    if sum(square[i][i] for i in range(n)) != magic_sum:
        return False
    if sum(square[i][n-1-i] for i in range(n)) != magic_sum:
        return False
    return True

def generate_magic_square(n):
    if n < 3 or n % 2 == 0:
        return None
    magic_square = [[0]*n for _ in range(n)]
    num, row, col = 1, n//2, n-1
    while num <= n*n:
        if row == -1 and col == n:  # 3rd condition
            row, col = 0, 0
        else:
            if col == n:  # handle wrap around for column
                col = 0
            if row < 0:  # handle wrap around for row
                row = n - 1
        if magic_square[row][col]:  # 2nd condition
            row = row + 1
            col = col - 2
            continue
        magic_square[row][col] = num
        num += 1
        row, col = row - 1, col + 1  # 1st condition
    return magic_square

def is_magic_square2(square):
    n = len(square)
    if any(len(row) != n for row in square):
        return False
    magic_sum = sum(square[0])
    for row in square:
        if sum(row) != magic_sum:
            return False
    for col in range(n):
        if sum(square[row][col] for row in range(n)) != magic_sum:
            return False
    if sum(square[i][i] for i in range(n)) != magic_sum:
        return False
    if sum(square[i][n-1-i] for i in range(n)) != magic_sum:
        return False
    return True
```

