def maximum_total_path_sum(triangle):
    if not triangle:
        return 0
    n = len(triangle)
    dp = triangle[-1].copy()
    for row in range(n-2, -1, -1):
        for col in range(row+1):
            dp[col] = triangle[row][col] + max(dp[col], dp[col+1])
    return dp[0]
```

