```python
def find_longest_chain(pairs):
    n = len(pairs)
    if n == 0:
        return 0

    # Sort pairs based on the first element
    pairs.sort(key=lambda x: x[0])

    # Initialize the dp array
    dp = [1] * n

    # Fill dp array
    for i in range(1, n):
        for j in range(i):
            if pairs[i][0] > pairs[j][1] and dp[i] < dp[j] + 1:
                dp[i] = dp[j] + 1

    # Return the maximum value in dp array
    return max(dp)
```

