def largest_divisible_subset(nums):
    if not nums:
        return []
    nums.sort()
    dp = [[] for _ in range(len(nums))]
    for i in range(len(nums)):
        dp[i] = [nums[i]]
        for j in range(i):
            if nums[i] % nums[j] == 0 and len(dp[j]) + 1 > len(dp[i]):
                dp[i] = dp[j] + [nums[i]]
    return max(dp, key=len)
```

