def find_median_sorted_arrays(nums1, nums2):
    def find_kth_element(arr1, arr2, k):
        if not arr1:
            return arr2[k]
        if not arr2:
            return arr1[k]
        mid1, mid2 = len(arr1) // 2, len(arr2) // 2
        mid1_val, mid2_val = arr1[mid1], arr2[mid2]

        # When k is bigger than the sum of a and b's mid index
        if mid1 + mid2 < k:
            # if arr1's mid is bigger, arr1's front part doesn't include the kth element
            if mid1_val > mid2_val:
                return find_kth_element(arr1, arr2[mid2+1:], k - mid2 - 1)
            else:
                return find_kth_element(arr1[mid1+1:], arr2, k - mid1 - 1)
        # When k is smaller than the sum of a and b's mid index
        else:
            # if arr1's mid is bigger, arr1's back part includes the kth element
            if mid1_val > mid2_val:
                return find_kth_element(arr1[:mid1], arr2, k)
            else:
                return find_kth_element(arr1, arr2[:mid2], k)

    total_length = len(nums1) + len(nums2)
    if total_length % 2 == 1:
        return find_kth_element(nums1, nums2, total_length // 2)
    else:
        return 0.5 * (find_kth_element(nums1, nums2, total_length // 2 - 1) + find_kth_element(nums1, nums2, total_length // 2))
```

