def first_digit_factorial(n):
    if n == 0 or n == 1:
        return 1
    factorial = 1
    for i in range(2, n + 1):
        factorial *= i
        while factorial % 10 == 0:
            factorial //= 10
        factorial = factorial % 1000000000
    return int(str(factorial)[0])
```

