def min_swaps_to_convert(s1: str, s2: str) -> int:
    if s1 == s2:
        return 0
    m, n = len(s1), len(s2)
    if m != n:
        return -1
    mismatch = sum(1 for i in range(n) if s1[i] != s2[i])
    if mismatch % 2 != 0:
        return -1
    return mismatch // 2
```

