```python
def sum_of_products(arr):
    n = len(arr)
    prefix_sum = [0] * (n + 1)
    for i in range(n):
        prefix_sum[i + 1] = prefix_sum[i] + arr[i]

    total_sum = 0
    for i in range(n):
        for j in range(i, n):
            total_sum += (prefix_sum[j + 1] - prefix_sum[i]) * (j - i + 1)

    return total_sum
```

```python
def left_insertion_point(sorted_list, target):
    left, right = 0, len(sorted_list)
    while left < right:
        mid = (left + right) // 2
        if sorted_list[mid] < target:
            left = mid + 1
        else:
            right = mid
    return left
```

