import math

def is_triangular_number(x):
    n = (math.sqrt(1 + 8 * x) - 1) / 2
    return n == int(n)

def find_smallest_triangular_index(digits):
    low, high = 10**(digits - 1), 10**digits
    while low < high:
        mid = (low + high) // 2
        if is_triangular_number(mid * (mid + 1) // 2):
            high = mid
        else:
            low = mid + 1
    return low

