def find_divisible_numbers(start, end):
    def all_divisible_by_digits(number):
        for digit in str(number):
            if digit == '0' or number % int(digit) != 0:
                return False
        return True

    divisible_numbers = [num for num in range(start, end + 1) if all_divisible_by_digits(num)]
    return divisible_numbers
```

