def min_swaps_to_equalize(s1: str, s2: str) -> int:
    if s1 == s2:
        return 0
    ones_diff = sum(c1 != c2 for c1, c2 in zip(s1, s2))
    if ones_diff % 2 != 0:
        return -1
    swaps = 0
    ones = sum(c == '1' for c in s1)
    for i in range(len(s1)):
        if s1[i] == '1' and s2[i] == '0':
            swaps += 1
            ones -= 1
        elif s1[i] == '0' and s2[i] == '1':
            ones += 1
    return swaps + (ones // 2)
```

