def sum_of_prime_divisors(n):
    i = 2
    result = 0
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            if i > 2 and all(i % d != 0 for d in range(2, int(i**0.5) + 1)):
                result += i
            elif i == 2:
                result += i
    if n > 1 and n != 2:
        if all(n % d != 0 for d in range(2, int(n**0.5) + 1)):
            result += n
    return result
```

